<template>
  <view class="charts-box">
    <qiun-data-charts 
      type="line"
      :opts="opts"
      :chartData="chartData"
    />
  </view>
</template>

<script>
export default {
  data() {
    return {
      chartData: {},
      //您可以通过修改 config-ucharts.js 文件中下标为 ['line'] 的节点来配置全局默认参数，如都是默认参数，此处可以不传 opts 。实际应用过程中 opts 只需传入与全局默认参数中不一致的【某一个属性】即可实现同类型的图表显示不同的样式，达到页面简洁的需求。
      opts: {
        update:true,
        duration:0,
        animation:false,
        color: ["#1890FF","#91CB74","#FAC858","#EE6666","#73C0DE","#3CA272","#FC8452","#9A60B4","#ea7ccc"],
        padding: [15,10,0,15],
        dataLabel: false,
        dataPointShape: false,
        enableScroll: false,
        legend: {
          position:'top',
          float:'center'
        },
        xAxis: {
          fontColor:'transparent',
          axisLineColor:'#4E8AB1',
          gridType:'dash',
        },
        yAxis: {
        gridType:'dash',
          showTitle:true,
          data: [
            {
              min: 0,
              max:120,
              axisLine:false,
              titleFontColor:'#676767',
              axisLineColor:'#676767',
              title:'(次数)',
              titleOffsetY:-5,
              titleOffsetX:-7,
              titleFontSize:16
            }
          ]
        },
        extra: {
          line: {
            type: "curve",
            width: 2,
            activeType: "hollow",
            linearType: "custom"
          }
        }
      }
    };
  },
  mounted() {
    this.getServerData();
  },
  methods: {
    getServerData(item) {
      if(!item){
      //模拟从服务器获取数据时的延时
      setTimeout(() => {
        //模拟服务器返回数据，如果数据格式和标准格式不同，需自行按下面的格式拼接
          let res = {
              categories: ["2018","2019","2020","2021","2022","2023"],
              series: [
                {
                  name: "呼吸",
                  linearColor: [
                    [
                      0,
                      "#1890FF"
                    ],
                    [
                      0.25,
                      "#00B5FF"
                    ],
                    [
                      0.5,
                      "#00D1ED"
                    ],
                    [
                      0.75,
                      "#00E6BB"
                    ],
                    [
                      1,
                      "#90F489"
                    ]
                  ],
                  data: [0,0,0,0,0,0]
                },
                {
                  name: "心率",
                  linearColor: [
                    [
                      0,
                      "#91CB74"
                    ],
                    [
                      0.25,
                      "#2BDCA8"
                    ],
                    [
                      0.5,
                      "#2AE3A0"
                    ],
                    [
                      0.75,
                      "#C4D06E"
                    ],
                    [
                      1,
                      "#F2D375"
                    ]
                  ],
                  data: [0,0,0,0,0,0]
                }
              ]
            };
          this.chartData = JSON.parse(JSON.stringify(res));
        }, 500);
      }else{
        var  breath = item.map((v)=>{return v.breath})
         var  heart = item.map((v)=>{return v.heart})
         var  time = item.map((v)=>{return v.time})
         let res = {
          categories: time,
          series: [
                {
                  name: "呼吸",
                  linearColor: [
                    [
                      0,
                      "#1890FF"
                    ],
                    [
                      0.25,
                      "#00B5FF"
                    ],
                    [
                      0.5,
                      "#00D1ED"
                    ],
                    [
                      0.75,
                      "#00E6BB"
                    ],
                    [
                      1,
                      "#90F489"
                    ]
                  ],
                  data: breath
                },
                {
                  name: "心率",
                  linearColor: [
                    [
                      0,
                      "#91CB74"
                    ],
                    [
                      0.25,
                      "#2BDCA8"
                    ],
                    [
                      0.5,
                      "#2AE3A0"
                    ],
                    [
                      0.75,
                      "#C4D06E"
                    ],
                    [
                      1,
                      "#F2D375"
                    ]
                  ],
                  data: heart
                }
              ]
            };
          this.chartData = JSON.parse(JSON.stringify(res));
      }

    },
  }
};
</script>

<style scoped>
  /* 请根据实际需求修改父元素尺寸，组件自动识别宽高 */
  .charts-box {
    width: 100%;
    height: 230px;
  }
